Directions = {'x+': [Axis.X, +1], 'x-': [Axis.X, -1], 'y+': [Axis.Y, +1], 'y-': [Axis.Y, -1], 'z+': [Axis.Z, +1], 'z-': [Axis.Z, -1]}

